selector_to_html = {"a[href=\"install.html#known-issues-and-workarounds\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">9. Known issues and workarounds<a class=\"headerlink\" href=\"#known-issues-and-workarounds\" title=\"Link to this heading\">#</a></h2><h3>9.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> imports <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code> from Triton, which FlagTree does not provide. Add a compatibility shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"install.html#configure-and-run-the-training\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Configure and run the training<a class=\"headerlink\" href=\"#configure-and-run-the-training\" title=\"Link to this heading\">#</a></h2><h3>6.1 Model configuration<a class=\"headerlink\" href=\"#model-configuration\" title=\"Link to this heading\">#</a></h3><p>Edit <code class=\"docutils literal notranslate\"><span class=\"pre\">./examples/qwen3/conf/train/0_6b.yaml</span></code> to point at the local dataset and tokenizer, and shrink the batch sizes so the job fits a single node:</p>", "a[href=\"install.html#switch-to-the-flagos-compiler-and-operator-library\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Switch to the FlagOS compiler and operator library<a class=\"headerlink\" href=\"#switch-to-the-flagos-compiler-and-operator-library\" title=\"Link to this heading\">#</a></h2><p>The training job above uses the vendor operator library. To run on the FlagOS stack instead, replace Triton with FlagTree and install FlagGems.</p>", "a[href=\"install.html#install-the-components\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Install the components<a class=\"headerlink\" href=\"#install-the-components\" title=\"Link to this heading\">#</a></h2><p>The tags validated on each platform (FlagTree tracks a different Triton version on Ascend):</p>", "a[href=\"requirements.html#supported-hardwares\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supported Hardwares<a class=\"headerlink\" href=\"#supported-hardwares\" title=\"Link to this heading\">#</a></h2><p>Training and inference have additionally been validated end to end on the following platforms:</p>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><h2>Supported Hardwares<a class=\"headerlink\" href=\"#supported-hardwares\" title=\"Link to this heading\">#</a></h2><p>Training and inference have additionally been validated end to end on the following platforms:</p>", "a[href=\"install.html#clone-the-repositories\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Clone the repositories<a class=\"headerlink\" href=\"#clone-the-repositories\" title=\"Link to this heading\">#</a></h2>", "a[href=\"install.html#expected-output\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Expected output<a class=\"headerlink\" href=\"#expected-output\" title=\"Link to this heading\">#</a></h2><p>A healthy single-card run on Ascend (Qwen3, <code class=\"docutils literal notranslate\"><span class=\"pre\">global_batch_size:</span> <span class=\"pre\">32</span></code>):</p>", "a[href=\"install.html#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">10. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install Megatron-LM-FL<a class=\"headerlink\" href=\"#install-megatron-lm-fl\" title=\"Link to this heading\">#</a></h1><p>This guide covers installing Megatron-LM-FL starting from a pre-built Docker image, and validating the installation with an end-to-end Qwen3 training job. Installation starts from the Docker image; the component packages are then installed inside the container.</p><p>The workflow uses the following FlagOS components together:</p>", "a[href=\"install.html#supported-platforms\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Supported platforms<a class=\"headerlink\" href=\"#supported-platforms\" title=\"Link to this heading\">#</a></h2><p>End-to-end validation has been completed on MetaX, Hygon, Ascend, and T-Head PPU.</p>", "a[href=\"#getting-started-with-megatron-lm-fl\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started with Megatron-LM-FL<a class=\"headerlink\" href=\"#getting-started-with-megatron-lm-fl\" title=\"Link to this heading\">#</a></h1><p>This section covers the requirements for installing Megatron-LM-FL and guides you through installing Megatron-LM-FL on different hardware platforms.</p>", "a[href=\"requirements.html#flagos-components-and-versions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">FlagOS components and versions<a class=\"headerlink\" href=\"#flagos-components-and-versions\" title=\"Link to this heading\">#</a></h2><p>The complete FlagOS stack used with Megatron-LM-FL, with the validated version on each platform:</p>", "a[href=\"install.html#prepare-the-dataset-and-tokenizer\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Prepare the dataset and tokenizer<a class=\"headerlink\" href=\"#prepare-the-dataset-and-tokenizer\" title=\"Link to this heading\">#</a></h2>", "a[href=\"install.html#get-the-image-and-start-the-container\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Get the image and start the container<a class=\"headerlink\" href=\"#get-the-image-and-start-the-container\" title=\"Link to this heading\">#</a></h2><p>Megatron-LM-FL runs in a pre-built Docker image. Go to the <a class=\"reference external\" href=\"https://flagos.io/Home\">FlagOS main page</a>, pick the image for your hardware from the download list in the middle of the page, and follow the on-page instructions to pull the image, enter the container, and start it.</p><p>Before installing the packages below, check inside the container that your device is visible (section 1 lists the command for each platform).</p>", "a[href=\"requirements.html#operating-system\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Operating system<a class=\"headerlink\" href=\"#operating-system\" title=\"Link to this heading\">#</a></h2><p>Linux (official), WSL2 (limited support)</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
